// Offline basemap of cached cells (SPEC §7.7): Protomaps "grayscale" layers,
// generated by tools/build_basemap_style.mjs with local place names.
// The source can only have one max zoom; the backend reports the lowest max
// zoom of the cached cells, and the map over-zooms above it.
import { url } from './api.js';
import { addToGroup } from './layers.js';

let layers = [];
let version = 1;
let maxzoom = null;

export async function loadBasemapStyle() {
  const response = await fetch(url('/app/vendor/basemap/grayscale-layers.json'));
  layers = await response.json();
}

const tiles = () => [url(`/tiles/basemap/{z}/{x}/{y}.mvt?v=${version}`)];

export function addBasemap(map, zoom) {
  maxzoom = zoom;
  map.addSource('basemap', { type: 'vector', tiles: tiles(), minzoom: 0, maxzoom: zoom });
  for (const layer of layers) addToGroup(map, 'basemap', layer);
}

export function setBasemapMaxzoom(map, zoom) {
  if (zoom === maxzoom || !map.getSource('basemap')) return;
  for (const layer of layers) if (map.getLayer(layer.id)) map.removeLayer(layer.id);
  map.removeSource('basemap');
  addBasemap(map, zoom);
}

export function refreshBasemap(map, newVersion) {
  version = newVersion;
  const source = map.getSource('basemap');
  if (source) source.setTiles(tiles());
}
